  app.querySelectorAll('[data-matrix-cell]').forEach(b=>b.onclick=()=>{trial.cell=Number(b.dataset.matrixCell);persist();renderMatrix();app.querySelector(`[data-matrix-cell="${trial.cell}"]`).focus();});
  app.querySelectorAll('[data-matrix-value]').forEach(b=>b.onclick=()=>{const value=Number(b.dataset.matrixValue);trial.matrix[trial.cell]=value;trial.checked=false;persist();renderMatrix();app.querySelector(`[data-matrix-value="${value}"]`).focus();});
